import{readFileSync,writeFileSync,existsSync}from'node:fs';import{createHash}from'node:crypto';import assert from'node:assert/strict';import{productionEnvironment,productionKeys,PRODUCTION_API_ORIGIN}from'../scripts/lib/production-database.mjs';import{practiceData}from'../scripts/lib/capacity-load.mjs';import{parseAvailabilityCatalog,parseAvailabilityWindow}from'../apps/web/src/lib/availability/contracts.ts';import{calculateAvailabilitySlots}from'../apps/web/src/lib/availability/calculate.ts';
const out='.verification/targeted-performance-pure-cpu-20261025.json';assert(!existsSync(out));const fixture=JSON.parse(readFileSync('.verification/targeted-performance-fixture-20261025.json'));assert(fixture.status==='seeded');const h=JSON.parse(readFileSync('.verification/targeted-performance-http-baseline-20261025.json'));const d=practiceData(1);const{env}=productionEnvironment(process.cwd()),{serviceKey}=productionKeys(env);async function rpc(name,input){const r=await fetch(PRODUCTION_API_ORIGIN+'/rest/v1/rpc/'+name,{method:'POST',headers:{authorization:'Bearer '+serviceKey,apikey:serviceKey,'content-type':'application/json'},body:JSON.stringify(input),signal:AbortSignal.timeout(15000)});assert(r.ok);return r.json();}
const rawCatalog=await rpc('get_availability_catalog',{p_business_id:d.business,p_public:false});const expected={businessId:d.business,scope:'internal'};const catalog=parseAvailabilityCatalog(rawCatalog,expected),rawWindow=await rpc('get_availability_window',{p_business_id:d.business,p_public:false,p_service_id:d.services[0],p_professional_ids:[d.professionals[0]],p_from_date:h.date,p_to_date:h.date,p_configuration_revision:catalog.configuration_revision});const ew={...expected,configurationRevision:catalog.configuration_revision,fromDate:h.date,toDate:h.date,professionalIds:[d.professionals[0]]};const window=parseAvailabilityWindow(rawWindow,ew);assert.throws(()=>parseAvailabilityCatalog({...rawCatalog,business_id:d.professionals[0]},expected));assert.throws(()=>parseAvailabilityWindow({...rawWindow,complete:false},ew));assert.throws(()=>parseAvailabilityWindow({...rawWindow,counts:{...rawWindow.counts,blocks:rawWindow.counts.blocks+1}},ew));
const input={business:catalog.business,service:catalog.services.find(s=>s.id===d.services[0]),professionals:catalog.professionals.filter(p=>p.id===d.professionals[0]),rules:catalog.rules,exceptions:window.exceptions,blocks:window.blocks,fromDate:h.date,toDate:h.date,publicOnly:false,requiredProfessionalIds:[],ignoreBreak:false,now:new Date()};assert(input.service);const measures=[];let slots;for(let i=0;i<30;i++){const cpu=process.cpuUsage(),t=performance.now();const c=parseAvailabilityCatalog(rawCatalog,expected),w=parseAvailabilityWindow(rawWindow,ew);slots=calculateAvailabilitySlots({...input,business:c.business,exceptions:w.exceptions,blocks:w.blocks});const use=process.cpuUsage(cpu);measures.push({iteration:i+1,wallMs:Math.round((performance.now()-t)*1000)/1000,cpuMs:(use.user+use.system)/1000});}assert(slots.length>0&&slots.every(s=>s.professional_id===d.professionals[0]));const r={at:new Date().toISOString(),scope:'Light sequential replay of actual parser+calculator source on this host, with owned production fixture JSON. Not WorkerCPU or a capacity criterion. First iteration retained; subsequent repetitions are warm.',runtime:fixture.runtime,slotCount:slots.length,blocks:window.blocks.length,catalogBytes:JSON.stringify(rawCatalog).length,windowBytes:JSON.stringify(rawWindow).length,adversarialContractChecks:3,sourceHashes:Object.fromEntries(['apps/web/src/lib/availability/calculate.ts','apps/web/src/lib/availability/contracts.ts'].map(p=>[p,createHash('sha256').update(readFileSync(p)).digest('hex')])),measurements:measures};writeFileSync(out,JSON.stringify(r,null,2)+'\n',{flag:'wx',mode:0o600});console.log({slots:r.slotCount,blocks:r.blocks,cold:r.measurements[0],warmMedianMs:r.measurements.slice(1).map(x=>x.cpuMs).sort((a,b)=>a-b)[14],checks:3,workerCpuCertified:false});
